notes.back:
// Why: Number("") is 0, so test for empty cells before converting. Splitting, trimming and
// filtering the lines first keeps the row logic simple.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/trim
function parseCsv(text) {
  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  if (lines.length === 0) return [];
  const headers = lines[0].split(",").map((h) => h.trim());
  return lines.slice(1).map((line) => {
    const cells = line.split(",").map((cell) => cell.trim());
    const row = {};
    headers.forEach((header, i) => {
      const cell = cells[i] ?? "";
      row[header] = cell !== "" && !Number.isNaN(Number(cell)) ? Number(cell) : cell;
    });
    return row;
  });
}

